  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: 10 * 9500 = 95000, no discount, 21% VAT = 19950
  // total = 95000 + 19950 = 114950
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 19950);
  assert.equal(totals.total, 114950);
});

test('invoiceTotals with multiple lines and different VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: 95000, 21% VAT = 19950
  // PRINT-A4: 3700, 9% VAT = 333
  // subtotal = 98700, discount = 0, vat = 20283, total = 118983
  assert.equal(totals.subtotal, 98700);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 20283);
  assert.equal(totals.total, 118983);
});

test('invoiceTotals with VAT and discount', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: 95000, discount 10% = 9500, discounted = 85500
  // VAT = 85500 * 21 / 100 = 17955
  // total = 95000 - 9500 + 17955 = 103455
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.total, 103455);
});

test('invoiceTotals with tier discount and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: 95000, gold tier discount 5% = 4750, discounted = 90250
  // VAT = 90250 * 21 / 100 = 18952.5 -> 18953 (rounded)
  // total = 95000 - 4750 + 18953 = 109203
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18953);
  assert.equal(totals.total, 109203);
});

test('invoiceTotals with mixed lines, discounts, and VAT', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 15 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: 95000, gold tier 5% discount = 4750, discounted = 90250, VAT 21% = 18953
  // LOGO-PACK: 120000, explicit 15% discount = 18000, discounted = 102000, VAT 21% = 21420
  // WORKSHOP-DAY: 60000, gold tier 5% discount = 3000, discounted = 57000, VAT 0% = 0
  // subtotal = 275000, discount = 25750, vat = 40373, total = 289623
  assert.equal(totals.subtotal, 275000);
  assert.equal(totals.discount, 25750);
  assert.equal(totals.vat, 40373);
  assert.equal(totals.total, 289623);
});

test('invoiceTotals clamps total to zero with extreme discount and low VAT', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'WORKSHOP-DAY',
        name: 'Workshop (day)',
        qty: 1,
        unitPrice: 100,
        vatRate: 0,
        discountPercent: 100,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  // subtotal = 100, discount = 100, vat = 0
  // total should be clamped to 0, not -0
  assert.equal(totals.subtotal, 100);
  assert.equal(totals.discount, 100);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

